code_examples.code:
html   { font-size: 30px; }
footer { font-size: 80px; }

/* inside the footer: */
h2.em  { font-size: 2em;  } /* 2 x footer = 160px */
h2.rem { font-size: 2rem; } /* 2 x html   = 60px, footer ignored */

p.a { font-family: Helvetica, sans-serif; }
p.b { font-family: "Times New Roman", serif; }   /* quotes: name has spaces */
p.c { font-family: "Caveat", cursive; }          /* Google Font, generic backup */

h1 { font-weight: bold; }
p  { font-weight: 300; }
span { font-weight: bolder; } /* relative to parent */

